  "inlineSchema": "datasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ngenerator erd {\n  provider = \"prisma-erd-generator\"\n  output   = \"../../docs/Bizloom_ERD.svg\"\n  theme    = \"neutral\"\n}\n\nmodel User {\n  id            String         @id @default(uuid())\n  email         String         @unique\n  password      String\n  name          String\n  role          String         @default(\"EMPLOYEE\") // ADMIN, MANAGER, EMPLOYEE, ACCOUNTANT\n  isVerified    Boolean        @default(false)\n  otp           String?\n  otpExpiresAt  DateTime?\n  lastLogin     DateTime?\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n  refreshTokens RefreshToken[]\n}\n\nmodel RefreshToken {\n  id        String   @id @default(uuid())\n  token     String   @unique\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n}\n\nmodel Product {\n  id                 String              @id @default(uuid())\n  name               String\n  sku                String              @unique\n  description        String?\n  price              Float\n  cost               Float\n  quantity           Int\n  minStockLevel      Int                 @default(5)\n  category           String\n  createdAt          DateTime            @default(now())\n  updatedAt          DateTime            @updatedAt\n  stockHistory       StockHistory[]\n  orderItems         OrderItem[]\n  purchaseOrderItems PurchaseOrderItem[]\n}\n\nmodel StockHistory {\n  id          String   @id @default(uuid())\n  productId   String\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  change      Int // Pos for restock, neg for sales\n  type        String // \"SALE\", \"RESTOCK\", \"ADJUSTMENT\"\n  referenceId String? // Links to OrderId if it is a sale\n  notes       String?\n  createdAt   DateTime @default(now())\n}\n\nmodel Customer {\n  id        String   @id @default(uuid())\n  name      String\n  email     String   @unique\n  phone     String?\n  address   String?\n  company   String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  orders    Order[]\n}\n\nmodel Order {\n  id           String      @id @default(uuid())\n  orderNumber  String      @unique\n  customerId   String\n  customer     Customer    @relation(fields: [customerId], references: [id], onDelete: Restrict)\n  status       String // \"PAID\", \"UNPAID\", \"PARTIAL\"\n  subtotal     Float\n  tax          Float\n  total        Float\n  paymentTerms String? // e.g. \"NET 30\", \"DUE ON RECEIPT\"\n  createdAt    DateTime    @default(now())\n  updatedAt    DateTime    @updatedAt\n  items        OrderItem[]\n}\n\nmodel OrderItem {\n  id        String  @id @default(uuid())\n  orderId   String\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Restrict)\n  quantity  Int\n  price     Float // Price at the time of sale\n}\n\nmodel Supplier {\n  id             String          @id @default(uuid())\n  name           String\n  email          String          @unique\n  phone          String?\n  address        String?\n  company        String?\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n  purchaseOrders PurchaseOrder[]\n}\n\nmodel PurchaseOrder {\n  id           String              @id @default(uuid())\n  orderNumber  String              @unique\n  supplierId   String\n  supplier     Supplier            @relation(fields: [supplierId], references: [id], onDelete: Restrict)\n  status       String // \"PENDING\", \"RECEIVED\", \"CANCELLED\"\n  subtotal     Float\n  tax          Float\n  total        Float\n  paymentTerms String? // e.g. \"NET 30\", \"DUE ON RECEIPT\"\n  createdAt    DateTime            @default(now())\n  updatedAt    DateTime            @updatedAt\n  items        PurchaseOrderItem[]\n}\n\nmodel PurchaseOrderItem {\n  id              String        @id @default(uuid())\n  purchaseOrderId String\n  purchaseOrder   PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id], onDelete: Restrict)\n  quantity        Int\n  unitCost        Float\n}\n\nmodel Employee {\n  id         String       @id @default(uuid())\n  name       String\n  email      String       @unique\n  phone      String?\n  position   String\n  department String\n  salary     Float\n  status     String       @default(\"ACTIVE\") // ACTIVE, INACTIVE\n  hireDate   DateTime     @default(now())\n  createdAt  DateTime     @default(now())\n  updatedAt  DateTime     @updatedAt\n  attendance Attendance[]\n}\n\nmodel Attendance {\n  id         String    @id @default(uuid())\n  employeeId String\n  employee   Employee  @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  date       DateTime  @default(now())\n  checkIn    DateTime  @default(now())\n  checkOut   DateTime?\n  status     String    @default(\"PRESENT\") // PRESENT, LATE, ABSENT\n}\n\nmodel Transaction {\n  id          String   @id @default(uuid())\n  type        String // INCOME, EXPENSE\n  category    String\n  amount      Float\n  description String?\n  date        DateTime @default(now())\n  createdAt   DateTime @default(now())\n}\n\nmodel SystemLog {\n  id          String   @id @default(uuid())\n  userId      String?\n  userEmail   String?\n  action      String // e.g. \"LOGIN\", \"FAILED_LOGIN\", \"CREATE_PRODUCT\"\n  module      String // e.g. \"AUTH\", \"INVENTORY\", \"SALES\"\n  description String?\n  ipAddress   String?\n  severity    String   @default(\"INFO\") // INFO, WARNING, ERROR, CRITICAL\n  timestamp   DateTime @default(now())\n}\n",
